<style>
.ncc{max-width:1500px;margin:auto;padding:28px 20px 50px;color:#172b4d}.hero,.card{background:#fff;border:1px solid #dbe4ef;border-radius:24px;box-shadow:0 14px 34px rgba(29,43,87,.08)}.hero{padding:30px;background:linear-gradient(135deg,#fff,#f7fbff 70%,#fff8e7)}.hero h1{font-size:clamp(1.7rem,3vw,2.5rem);font-weight:800;letter-spacing:-.03em}.hero p{color:#627086;max-width:950px;margin-top:8px}.grid{display:grid;grid-template-columns:390px 1fr;gap:22px;margin-top:22px}.card{padding:22px}.card h2{font-weight:800;font-size:1.05rem}.label{display:block;margin:16px 0 7px;font-size:.76rem;font-weight:800;text-transform:uppercase;letter-spacing:.07em;color:#718096}.fields{display:grid;grid-template-columns:1fr 1fr;gap:10px}.input{width:100%;border:1px solid #cfd9e6;border-radius:12px;padding:11px 12px;background:#fbfdff}.actions{display:flex;gap:9px;flex-wrap:wrap;margin-top:18px}.btn{border:0;border-radius:12px;padding:11px 15px;font-weight:800;cursor:pointer}.primary{background:#1d2b57;color:#fff}.secondary{background:#edf2f8;color:#233a60}.danger{background:#fff0f0;color:#a83232}.btn:disabled{opacity:.5;cursor:not-allowed}.note{margin-top:14px;padding:13px;border-radius:13px;background:#f4f7fb;color:#607086;font-size:.84rem;line-height:1.55}.kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}.kpi{border:1px solid #e0e7ef;border-radius:15px;padding:13px;background:#fafcff}.kpi span{display:block;font-size:.7rem;text-transform:uppercase;color:#738096;font-weight:800}.kpi strong{font-size:1.25rem}.progress{height:9px;background:#edf2f7;border-radius:99px;overflow:hidden;margin:15px 0}.progress div{height:100%;background:linear-gradient(90deg,#1d2b57,#f4b400);width:0}.live{display:flex;align-items:center;gap:9px;color:#66758a;margin-bottom:12px}.spin{width:17px;height:17px;border:2px solid #d6deea;border-top-color:#1d2b57;border-radius:50%;animation:s .7s linear infinite}.hide{visibility:hidden}@keyframes s{to{transform:rotate(360deg)}}.wrap{overflow:auto;border:1px solid #e0e7ef;border-radius:15px}.table{width:100%;border-collapse:collapse;min-width:800px}.table th{background:#f7f9fc;text-align:left;padding:11px 13px;font-size:.72rem;text-transform:uppercase;color:#65748b}.table td{padding:12px 13px;border-top:1px solid #edf1f5;font-size:.88rem}.empty{text-align:center;padding:40px;color:#7a8799}.badge{padding:5px 9px;border-radius:99px;background:#e7f7ef;color:#147a53;font-weight:800;font-size:.74rem}.badge.off{background:#fff0e7;color:#9a4a12}.log{margin-top:15px;max-height:160px;overflow:auto;background:#111827;color:#dbe4ef;border-radius:13px;padding:11px;font:12px/1.5 monospace}
