<main class="ncc"><section class="hero"><h1>Exploration progressive des NCC</h1><p>Définissez une plage numérique. FINEA génère automatiquement les NCC à 7 chiffres et teste les lettres A à Z, un appel à la fois. Les entreprises trouvées apparaissent immédiatement et la progression est conservée dans ce navigateur.</p></section><div class="grid"><section class="card"><h2>Plage de recherche</h2><div class="fields"><div><label class="label" for="start">Début</label><input class="input" id="start" inputmode="numeric" maxlength="7" value="2150000"></div><div><label class="label" for="end">Fin</label><input class="input" id="end" inputmode="numeric" maxlength="7" value="2160000"></div></div><label class="label" for="delay">Intervalle</label><input class="input" id="delay" type="number" min="2500" max="30000" step="500" value="3500"><div class="actions"><button class="btn primary" id="startBtn">Démarrer</button><button class="btn secondary" id="pauseBtn" disabled>Pause</button><button class="btn danger" id="resetBtn">Réinitialiser</button></div><div class="note">Ordre : <b>2150000A → … → 2150000Z → 2150001A</b>. Les nombres composés d'un même chiffre (0000000, 1111111, etc.) sont ignorés. Une plage est volontairement limitée à 10 000 numéros, soit au maximum 260 000 combinaisons par session de recherche. En cas de HTTP 429, FINEA attend automatiquement avant de reprendre.</div></section><section class="card"><div class="kpis"><div class="kpi"><span>Combinaisons</span><strong id="total">0</strong></div><div class="kpi"><span>Testées</span><strong id="tested">0</strong></div><div class="kpi"><span>Trouvées</span><strong id="found">0</strong></div><div class="kpi"><span>NCC courant</span><strong id="current">—</strong></div></div><div class="progress"><div id="bar"></div></div><div class="live"><span id="spinner" class="spin hide"></span><span id="status">En attente.</span></div><div class="wrap"><table class="table"><thead><tr><th>#</th><th>NCC</th><th>Entreprise</th><th>Régime</th><th>Activité</th><th>Inscription</th></tr></thead><tbody id="rows"></tbody></table><div id="empty" class="empty">Aucune entreprise trouvée pour le moment.</div></div><div id="log" class="log"><div>Prêt.</div></div></section></div></main>
<script>
(()=>{const csrf=<?=json_encode($csrf,JSON_UNESCAPED_SLASHES)?>,endpoint='../api/dgi_ncc_lookup.php',letters='ABCDEFGHIJKLMNOPQRSTUVWXYZ',KEY='finea_dgi_ncc_range_v2';const $=id=>document.getElementById(id),els={start:$('start'),end:$('end'),delay:$('delay'),startBtn:$('startBtn'),pauseBtn:$('pauseBtn'),resetBtn:$('resetBtn'),total:$('total'),tested:$('tested'),found:$('found'),current:$('current'),bar:$('bar'),spinner:$('spinner'),status:$('status'),rows:$('rows'),empty:$('empty'),log:$('log')};let state=null,running=false,aborter=null;const wait=ms=>new Promise(r=>setTimeout(r,ms)),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));function sameDigits(n){return /^(\d)\1{6}$/.test(String(n).padStart(7,'0'))}function countValid(a,b){let skipped=0;for(let d=0;d<=9;d++){const n=Number(String(d).repeat(7));if(n>=a&&n<=b)skipped++;}return Math.max(0,b-a+1-skipped)}function log(m){const d=document.createElement('div');d.textContent=`[${new Date().toLocaleTimeString('fr-FR')}] ${m}`;els.log.appendChild(d);els.log.scrollTop=els.log.scrollHeight}function persist(){if(state)localStorage.setItem(KEY,JSON.stringify(state))}function nextCandidate(){while(state.number<=state.end&&sameDigits(state.number)){state.number++;state.letter=0}if(state.number>state.end)return null;return String(state.number).padStart(7,'0')+letters[state.letter]}function advance(){state.tested++;state.letter++;if(state.letter>=26){state.letter=0;state.number++}persist();renderStats()}function renderStats(){if(!state){els.total.textContent='0';els.tested.textContent='0';els.found.textContent='0';els.current.textContent='—';els.bar.style.width='0%';return}els.total.textContent=state.total.toLocaleString('fr-FR');els.tested.textContent=state.tested.toLocaleString('fr-FR');els.found.textContent=state.companies.length.toLocaleString('fr-FR');els.current.textContent=nextCandidate()||'Terminé';els.bar.style.width=(state.total?Math.min(100,state.tested/state.total*100):0)+'%'}function addCompany(c,restore=false){els.empty.hidden=true;const tr=document.createElement('tr'),off=String(c.statusActivity||'').toLowerCase()==='cessation',date=c.firstRegistrationDate||c.registeredAt;tr.innerHTML=`<td>${els.rows.children.length+1}</td><td><b>${esc(c.ncc)}</b></td><td>${esc(c.name)}</td><td>${esc(c.taxRegime||'—')}</td><td><span class="badge ${off?'off':''}">${esc(c.statusActivityLabel||c.statusActivity||'—')}</span></td><td>${date?new Date(date).toLocaleDateString('fr-FR'):'—'}</td>`;els.rows.appendChild(tr);if(!restore)log(`Trouvé : ${c.ncc} — ${c.name}`)}function restore(){try{const s=JSON.parse(localStorage.getItem(KEY)||'null');if(!s||!Array.isArray(s.companies))return;state=s;els.start.value=String(s.start).padStart(7,'0');els.end.value=String(s.end).padStart(7,'0');els.delay.value=s.delay||3500;s.companies.forEach(c=>addCompany(c,true));renderStats();els.status.textContent=`Progression restaurée : ${s.tested.toLocaleString('fr-FR')} tests.`}catch(e){localStorage.removeItem(KEY)}}function createState(){const a=Number(els.start.value),b=Number(els.end.value);if(!/^\d{1,7}$/.test(els.start.value)||!/^\d{1,7}$/.test(els.end.value)||b<a){els.status.textContent='Plage invalide.';return false}if(b-a>9999){els.status.textContent='La plage ne peut pas dépasser 10 000 numéros.';return false}const valid=countValid(a,b);state={start:a,end:b,number:a,letter:0,tested:0,total:valid*26,delay:Math.max(2500,Math.min(30000,Number(els.delay.value)||3500)),companies:[]};els.rows.innerHTML='';els.empty.hidden=false;els.log.innerHTML='<div>Nouvelle recherche.</div>';persist();renderStats();return true}async function lookup(ncc){aborter=new AbortController();const r=await fetch(endpoint,{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json'},credentials:'same-origin',signal:aborter.signal,body:JSON.stringify({_csrf:csrf,ncc})});let d={};try{d=await r.json()}catch(e){}return{r,d}}function setRun(v){running=v;els.startBtn.disabled=v;els.pauseBtn.disabled=!v;els.spinner.classList.toggle('hide',!v)}async function run(){if(!state||state.start!==Number(els.start.value)||state.end!==Number(els.end.value)){if(!createState())return}if(!nextCandidate()){els.status.textContent='Traitement terminé.';return}state.delay=Math.max(2500,Math.min(30000,Number(els.delay.value)||3500));setRun(true);while(running){const ncc=nextCandidate();if(!ncc)break;els.current.textContent=ncc;els.status.textContent=`Vérification de ${ncc}…`;try{const{r,d}=await lookup(ncc);if(r.status===429||d.rate_limited||d.remote_rate_limited){const retry=Math.max(2500,Number(d.retry_after_ms)||30000);els.status.textContent=`Limitation serveur — attente ${Math.ceil(retry/1000)} s`;log(`HTTP 429 sur ${ncc}; attente.`);await wait(retry);continue}if(d.ok&&d.found&&d.company){state.companies.push(d.company);addCompany(d.company);persist()}else if(!d.ok&&r.status>=500){log(`Erreur ${ncc}: ${d.message||r.status}`)}advance();if(running)await wait(state.delay)}catch(e){if(e.name!=='AbortError'){log(`Erreur réseau sur ${ncc}.`);await wait(10000)}}}setRun(false);els.status.textContent=nextCandidate()?'En pause.':'Traitement terminé.';persist()}els.startBtn.onclick=run;els.pauseBtn.onclick=()=>{running=false;if(aborter)aborter.abort();setRun(false);els.status.textContent='En pause.';persist()};els.resetBtn.onclick=()=>{running=false;if(aborter)aborter.abort();localStorage.removeItem(KEY);state=null;els.rows.innerHTML='';els.empty.hidden=false;els.log.innerHTML='<div>Progression réinitialisée.</div>';els.status.textContent='En attente.';setRun(false);renderStats()};restore();})();
</script>
